/** Point-cloud samplers. Every shape is generated by code: text, a brain field, a handshake, a 3D diamond. */
export type Pt = { x: number; y: number };
export type Pt3 = { x: number; y: number; z: number };
export type Rand = () => number;

export function mulberry32(seed: number): Rand {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function shuffle<T>(arr: T[], rand: Rand): T[] {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = a[i] as T;
    a[i] = a[j] as T;
    a[j] = tmp;
  }
  return a;
}

/** Take exactly n points from a list (cycling with jitter when the list is short). */
export function pick(list: Pt[], n: number, rand: Rand, jitter = 0.8): Pt[] {
  const out: Pt[] = [];
  if (n <= 0) return out;
  if (list.length === 0) {
    for (let i = 0; i < n; i++) out.push({ x: 0, y: 0 });
    return out;
  }
  const s = shuffle(list, rand);
  for (let i = 0; i < n; i++) {
    const p = s[i % s.length] as Pt;
    out.push(
      i < s.length
        ? { x: p.x, y: p.y }
        : { x: p.x + (rand() - 0.5) * jitter * 2, y: p.y + (rand() - 0.5) * jitter * 2 },
    );
  }
  return out;
}

function makeCanvas(w: number, h: number) {
  const c = document.createElement("canvas");
  c.width = Math.max(1, Math.ceil(w));
  c.height = Math.max(1, Math.ceil(h));
  const ctx = c.getContext("2d", { willReadFrequently: true });
  if (!ctx) throw new Error("2D canvas unavailable");
  return { c, ctx };
}

/** Pixels with alpha → points centred on the canvas middle. */
function scan(ctx: CanvasRenderingContext2D, w: number, h: number, step: number): Pt[] {
  const d = ctx.getImageData(0, 0, w, h).data;
  const pts: Pt[] = [];
  for (let y = 0; y < h; y += step) {
    for (let x = 0; x < w; x += step) {
      if ((d[(y * w + x) * 4 + 3] ?? 0) > 128) pts.push({ x: x - w / 2, y: y - h / 2 });
    }
  }
  return pts;
}

export function textPoints(text: string, family: string, width: number, step = 2) {
  const probe = makeCanvas(4, 4).ctx;
  probe.font = `800 100px ${family}`;
  const m = probe.measureText(text).width || 1;
  const size = (100 * width) / m;
  const w = Math.ceil(width + size * 0.4);
  const h = Math.ceil(size * 1.5);
  const draw = (mode: "edge" | "fill") => {
    const { c, ctx } = makeCanvas(w, h);
    ctx.font = `800 ${size}px ${family}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillStyle = "#fff";
    ctx.strokeStyle = "#fff";
    if (mode === "fill") ctx.fillText(text, w / 2, h / 2);
    else {
      ctx.lineWidth = Math.max(1.5, size * 0.035);
      ctx.strokeText(text, w / 2, h / 2);
    }
    return scan(ctx, c.width, c.height, step);
  };
  return { edge: draw("edge"), fill: draw("fill") };
}

/**
 * Side-view brain from implicit functions:
 * cerebrum = wobbly super-ellipse, gyri = contour lines |g(x,y)| < ε of a warped trig field,
 * cerebellum = striped ellipse, brainstem = slanted strip.
 */
export function brainPoints(n: number, size: number, rand: Rand): Pt[] {
  const out: Pt[] = [];
  const half = size / 2;
  let guard = 0;
  while (out.length < n && guard++ < 400000) {
    const x = rand() * 2.1 - 1.05;
    const y = rand() * 1.95 - 0.95;
    const cy = y + 0.1;
    const ry = cy < 0 ? 0.74 : 0.5;
    const ang = Math.atan2(cy / ry, x);
    const wob = 1 + 0.03 * Math.sin(ang * 11) + 0.02 * Math.sin(ang * 5 + 1);
    const q = Math.sqrt(x * x + (cy / ry) ** 2) / wob;
    let ok = false;
    if (q < 1) {
      const g =
        Math.sin(8 * x + 2.4 * Math.sin(3.3 * y + 1.1) + 1.7 * Math.sin(5.1 * x * y)) *
        Math.cos(7.2 * y + 1.9 * Math.sin(2.9 * x + 0.4));
      const sylvian = Math.abs(y - (0.16 - 0.24 * (x - 0.1))) < 0.018 && x > -0.45 && x < 0.5;
      if (q > 0.95 || Math.abs(g) < 0.15 || sylvian) ok = true;
    }
    const ce = ((x - 0.52) / 0.34) ** 2 + ((y - 0.5) / 0.2) ** 2;
    if (!ok && ce < 1) {
      if (ce > 0.86 || Math.abs(Math.sin(26 * (y - 0.5) + 4 * (x - 0.52))) < 0.3) ok = true;
    }
    const x0 = 0.22 + (y - 0.4) * 0.25;
    if (!ok && y > 0.35 && y < 0.95 && Math.abs(x - x0) < 0.07 && q >= 1 && ce >= 1) {
      ok = rand() < 0.4;
    }
    if (ok) out.push({ x: x * half, y: y * half });
  }
  return out;
}

const LEFT_HAND = ["m11 17 2 2a1 1 0 1 0 3-3", "M3 3 2 14l6.5 6.5a1 1 0 1 0 3-3", "M3 4h8"];
const RIGHT_HAND = [
  "m14 14 2.5 2.5a1 1 0 1 0 3-3l-3.88-3.88a3 3 0 0 0-4.24 0l-.88.88a1 1 0 1 1-3-3l2.81-2.81a5.79 5.79 0 0 1 7.06-.87l.47.28a2 2 0 0 0 1.42.25L21 4",
  "m21 3 1 11h-2",
];

function strokeHand(paths: string[], size: number, outer: number, inner: number | null, step: number) {
  const w = size * 1.05;
  const h = size * 0.95;
  const { c, ctx } = makeCanvas(w, h);
  const k = size / 24;
  ctx.setTransform(k, 0, 0, k, c.width / 2 - 12 * k, c.height / 2 - 11.8 * k);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = outer;
  for (const d of paths) ctx.stroke(new Path2D(d));
  if (inner) {
    ctx.globalCompositeOperation = "destination-out";
    ctx.lineWidth = inner;
    for (const d of paths) ctx.stroke(new Path2D(d));
  }
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  return scan(ctx, c.width, c.height, step);
}

/** Two clasped hands, split per hand, as light-tube outlines (edge) plus a thin core line. */
export function handshakePoints(size: number, step = 2) {
  return {
    left: {
      edge: strokeHand(LEFT_HAND, size, 1.9, 1.2, step),
      core: strokeHand(LEFT_HAND, size, 0.45, null, step),
    },
    right: {
      edge: strokeHand(RIGHT_HAND, size, 1.9, 1.2, step),
      core: strokeHand(RIGHT_HAND, size, 0.45, null, step),
    },
  };
}

/** Round brilliant cut wireframe in unit space (y down). Points sampled along its facet edges. */
export function diamondPoints(n: number, rand: Rand): Pt3[] {
  const G = 16;
  const girdle: Pt3[] = [];
  for (let i = 0; i < G; i++) {
    const a = (i / G) * Math.PI * 2;
    girdle.push({ x: Math.cos(a), y: 0, z: Math.sin(a) });
  }
  const table: Pt3[] = [];
  for (let j = 0; j < 8; j++) {
    const a = (j / 8) * Math.PI * 2;
    table.push({ x: Math.cos(a) * 0.56, y: -0.42, z: Math.sin(a) * 0.56 });
  }
  const culet: Pt3 = { x: 0, y: 0.95, z: 0 };
  const g = (i: number) => girdle[((i % G) + G) % G] as Pt3;
  const tb = (j: number) => table[((j % 8) + 8) % 8] as Pt3;
  const edges: [Pt3, Pt3][] = [];
  for (let j = 0; j < 8; j++) {
    edges.push([tb(j), tb(j + 1)]);
    edges.push([tb(j), g(2 * j)]);
    edges.push([tb(j), g(2 * j - 1)]);
    edges.push([tb(j), g(2 * j + 1)]);
    edges.push([g(2 * j), culet]);
    const odd = g(2 * j + 1);
    const mid = {
      x: odd.x + (culet.x - odd.x) * 0.55,
      y: odd.y + (culet.y - odd.y) * 0.55,
      z: odd.z + (culet.z - odd.z) * 0.55,
    };
    edges.push([odd, mid]);
  }
  for (let i = 0; i < G; i++) edges.push([g(i), g(i + 1)]);
  const lens = edges.map(([a, b]) => Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z));
  const total = lens.reduce((s, l) => s + l, 0);
  const out: Pt3[] = [];
  for (let i = 0; i < n; i++) {
    let r = rand() * total;
    let e = 0;
    while (e < lens.length - 1 && r > (lens[e] ?? 0)) {
      r -= lens[e] ?? 0;
      e++;
    }
    const pair = edges[e] as [Pt3, Pt3];
    const u = r / (lens[e] || 1);
    const j = 0.006;
    out.push({
      x: pair[0].x + (pair[1].x - pair[0].x) * u + (rand() - 0.5) * j,
      y: pair[0].y + (pair[1].y - pair[0].y) * u + (rand() - 0.5) * j,
      z: pair[0].z + (pair[1].z - pair[0].z) * u + (rand() - 0.5) * j,
    });
  }
  return out;
}
